(function(n){n.JobLabContent=Object.assign(n.JobLabContent||{},{"KK-420":{scenario:{company:"Lá Xanh Tea House",supervisor:{name:"Phan Ngọc Diệp",role:{vi:"Giám đốc Sáng tạo",en:"Creative Director"}},ref_code:"PRN-0719",title:{vi:"Đúng hệ màu in. Đủ độ phân giải. Đúng bản quyền.",en:"Right print colours. Enough resolution. Licensed assets."},brief:{vi:"Bạn chuẩn bị file in offset 4 màu cho catalogue A4 PRN-0719 của thương hiệu trà. Ảnh bìa gốc rộng 2480 px, khai báo 300 ppi (tương đương 210 mm), nhưng trong dàn trang bị phóng 125% để tràn khổ. Nhà in yêu cầu hệ màu đúng quy trình in 4 màu và độ phân giải hiệu dụng tối thiểu 300 ppi. Đối chiếu phiếu kiểm tra file nháp với chuẩn chế bản đã duyệt, sửa hệ màu và độ phân giải hiệu dụng, rồi lập báo cáo có căn cứ.",en:"You are preparing the four-colour offset print file for A4 catalogue PRN-0719 of a tea brand. The cover image is 2480 px wide, tagged 300 ppi (equal to 210 mm), but it is scaled to 125% in the layout to run full bleed. The printer requires the colour mode used in four-colour printing and at least 300 ppi effective resolution. Compare the draft preflight sheet with the approved prepress standard, correct the colour mode and the effective resolution, then write an evidence-based report."},reference_title:{vi:"Chuẩn chế bản & báo cáo liên kết ảnh đã duyệt · PRN-0719",en:"Approved prepress standard & image link report · PRN-0719"},fields:[{id:"COLOR_MODE",label:{vi:"Hệ màu của file xuất in",en:"Colour mode of the print file"},initial:"RGB",expected:"CMYK",choices:["RGB","CMYK","LAB"],reference:"Chuẩn chế bản in offset",hint:{vi:"In offset 4 màu dùng mực cyan, magenta, vàng, đen; file RGB sẽ bị chuyển đổi tự động và lệch màu thương hiệu.",en:"Four-colour offset uses cyan, magenta, yellow and black inks; an RGB file gets auto-converted and shifts brand colours."}},{id:"EFF_PPI",label:{vi:"Độ phân giải hiệu dụng ảnh bìa (ppi)",en:"Effective resolution of the cover image (ppi)"},initial:"300",expected:"240",reference:"Báo cáo kiểm tra liên kết ảnh",ref_value:{vi:"Ảnh gốc 300 ppi (2480 px rộng 210 mm); tỷ lệ đặt trong dàn trang 125%",en:"Native 300 ppi (2480 px at 210 mm); placed at 125% scale in the layout"},hint:{vi:"Bản nháp ghi độ phân giải khai báo trong tệp ảnh; khi phóng to, mật độ điểm ảnh thực tế giảm theo tỷ lệ.",en:"The draft quotes the resolution tagged in the image file; scaling up lowers the real pixel density proportionally."}}],sop32:{vi:"Độ phân giải hiệu dụng = độ phân giải gốc / tỷ lệ phóng (hoặc số pixel / kích thước in tính bằng inch, 1 inch = 25.4 mm). Ảnh in offset phải đạt tối thiểu 300 ppi hiệu dụng; dưới ngưỡng phải thay ảnh hoặc giảm tỷ lệ.",en:"Effective resolution = native resolution / scale factor (or pixels / printed size in inches, 1 inch = 25.4 mm). Offset images need at least 300 ppi effective; below that, replace the image or reduce the scale."},context:{label:"PHIẾU KIỂM FILE / PRN-0719",metrics:[{label:{vi:"Khổ thành phẩm",en:"Trim size"},value:"A4 210 x 297 mm"},{label:{vi:"Chiều rộng ảnh bìa",en:"Cover image width"},value:"2480 px"},{label:{vi:"Tỷ lệ đặt ảnh",en:"Placed scale"},value:"125%"}]},crisis:{vi:"Account Manager nhắn: “Khách cần gấp, cứ dùng font bản cá nhân tải trên mạng và ghép mấy ảnh lấy trên mạng xã hội vào bìa. In 5.000 cuốn thôi, chẳng ai kiểm tra bản quyền đâu.”",en:"The account manager messages you: “The client is in a rush, just use the personal-use font from the web and paste some social media photos on the cover. It is only 5,000 copies, nobody checks licences.”"},options:{safe:{vi:"Không dùng font, ảnh chưa có giấy phép; báo Giám đốc Sáng tạo, đề xuất font có giấy phép thương mại, ảnh từ thư viện đã mua hoặc tự chụp và cập nhật tiến độ với khách bằng văn bản.",en:"Use no unlicensed fonts or images; inform the Creative Director, propose commercially licensed fonts and purchased or own photos, and update the client on timing in writing."},shortcut:{vi:"Dùng font bản cá nhân và ảnh lấy trên mạng để kịp in, bị khiếu nại thì gỡ sau.",en:"Use the personal-use font and web photos to hit the print date, remove them if anyone complains."},wait:{vi:"Gửi file cho nhà in mà không nhắc gì về bản quyền, để khách tự chịu.",en:"Send the file to the printer without raising licensing and let the client bear it."}},questions:{vi:["Vì sao file phải ở hệ CMYK và ảnh bìa chỉ còn 240 ppi hiệu dụng? Bạn xử lý ảnh này thế nào trước khi in?","Dùng font, ảnh chưa có giấy phép thương mại gây rủi ro gì cho khách và công ty? Bạn đề xuất phương án nào?"],en:["Why must the file be CMYK, and why is the cover only 240 ppi effective? How do you fix the image before printing?","What risks do unlicensed fonts and images create for the client and the agency? Which alternative do you propose?"]},hints:{vi:["So phiếu kiểm file nháp với chuẩn chế bản offset: in 4 màu dùng hệ màu nào?","Chia độ phân giải gốc cho tỷ lệ phóng theo SOP mục 3.2 rồi so với ngưỡng 300 ppi.","Đọc lại SOP mục 4.2: mọi tài sản thiết kế phải có giấy phép phù hợp mục đích thương mại."],en:["Compare the draft preflight sheet with the offset standard: which colour mode does four-colour printing use?","Divide the native resolution by the scale factor as in SOP 3.2, then compare with 300 ppi.","Re-read SOP 4.2: every design asset must be licensed for commercial use."]}},learning:{summary:{vi:"Nhà thiết kế đồ họa và nhận diện thương hiệu biến chiến lược thương hiệu thành hệ thống hình ảnh: logo, màu sắc, kiểu chữ, minh họa, bao bì, ấn phẩm in và tài sản số. Nghề tạo ra sự nhận biết nhất quán và giá trị cảm nhận cho thương hiệu, đòi hỏi tư duy ý tưởng, kỹ năng bố cục, hiểu kỹ thuật in, quản lý màu và tôn trọng sở hữu trí tuệ.",en:"A graphic and brand identity designer turns brand strategy into a visual system: logo, colour, typography, illustration, packaging, print and digital assets. The role builds consistent recognition and perceived value for the brand, and requires conceptual thinking, layout skills, print production knowledge, colour management and respect for intellectual property."},responsibilities:{vi:["Nghiên cứu brief, đối thủ và khách hàng mục tiêu để đề xuất định hướng hình ảnh.","Thiết kế logo, bảng màu, kiểu chữ và bộ quy chuẩn nhận diện thương hiệu.","Dàn trang ấn phẩm in, bao bì, biển hiệu và tài sản số theo quy chuẩn đã duyệt.","Chuẩn bị file in: hệ màu, tràn lề, độ phân giải, font, bản in thử và làm việc với nhà in.","Quản lý thư viện tài sản thiết kế cùng giấy phép font, ảnh, minh họa."],en:["Study the brief, competitors and target audience to propose a visual direction.","Design the logo, colour palette, typography and brand guidelines.","Lay out print collateral, packaging, signage and digital assets to the approved standard.","Prepare print files: colour mode, bleed, resolution, fonts and proofs, and work with printers.","Manage the design asset library and the licences for fonts, photos and illustrations."]},competencies:[{name:{vi:"Tư duy ý tưởng",en:"Concept development"},desc:{vi:"Chuyển chiến lược và câu chuyện thương hiệu thành ý tưởng hình ảnh có lập luận.",en:"Translate brand strategy and story into visual concepts backed by a clear rationale."}},{name:{vi:"Bố cục & kiểu chữ",en:"Layout & typography"},desc:{vi:"Dùng lưới, phân cấp, khoảng trắng và cặp font để thông điệp rõ ràng, dễ đọc.",en:"Use grids, hierarchy, white space and font pairing so the message reads clearly."}},{name:{vi:"Quản lý màu & chế bản",en:"Colour management & prepress"},desc:{vi:"Hiểu RGB, CMYK, màu pha, hồ sơ màu và yêu cầu kỹ thuật của từng phương pháp in.",en:"Understand RGB, CMYK, spot colours, colour profiles and the requirements of each print method."}},{name:{vi:"Hệ thống nhận diện",en:"Identity systems"},desc:{vi:"Xây dựng quy chuẩn logo, vùng an toàn, màu, chữ để nhiều đội áp dụng nhất quán.",en:"Build rules for logo use, clear space, colour and type so many teams apply them consistently."}},{name:{vi:"Sở hữu trí tuệ",en:"Intellectual property"},desc:{vi:"Kiểm tra giấy phép font, ảnh và tránh sao chép, gây nhầm lẫn với nhãn hiệu của người khác.",en:"Check font and image licences and avoid copying or confusing similarity with others' trademarks."}}],knowledge:{vi:["Luật Sở hữu trí tuệ số 50/2005/QH11 (đã sửa đổi, bổ sung): quyền tác giả, nhãn hiệu và kiểu dáng công nghiệp.","Nguyên lý màu: RGB cho màn hình, CMYK cho in 4 màu, màu pha cho màu thương hiệu cần chính xác.","Quản lý màu theo hồ sơ ICC và hồ sơ in cho giấy tráng phủ, không tráng phủ.","Kỹ thuật chế bản: tràn lề thường 3 mm, vùng an toàn, ảnh 300 ppi hiệu dụng cho in offset, nhúng font hoặc chuyển thành nét.","Chuẩn PDF/X (ISO 15930) để trao đổi file in tin cậy.","Nguyên tắc Gestalt và phân cấp thị giác trong bố cục."],en:["Intellectual Property Law No. 50/2005/QH11 (as amended): copyright, trademarks and industrial designs.","Colour basics: RGB for screens, CMYK for four-colour print, spot colours for exact brand colours.","Colour management with ICC profiles and print profiles for coated and uncoated stock.","Prepress practice: typically 3 mm bleed, safe zones, 300 ppi effective images for offset, embedded or outlined fonts.","The PDF/X standard (ISO 15930) for reliable print file exchange.","Gestalt principles and visual hierarchy in layout."]},tools:["Phần mềm thiết kế vector","Phần mềm xử lý ảnh bitmap","Phần mềm dàn trang","Công cụ kiểm tra file in (preflight)","Màn hình hiệu chuẩn và máy đo màu","Thư viện ảnh, font có giấy phép"],kpis:{vi:["Tỷ lệ file in đạt kiểm tra preflight ngay lần đầu.","Số vòng chỉnh sửa trung bình mỗi ấn phẩm.","Tỷ lệ tài sản thiết kế có giấy phép và hồ sơ nguồn đầy đủ (mục tiêu 100%).","Mức tuân thủ quy chuẩn nhận diện khi kiểm tra ngẫu nhiên ấn phẩm."],en:["Share of print files passing preflight first time.","Average revision rounds per piece.","Share of design assets with licences and source records (target 100%).","Brand guideline compliance in random checks of collateral."]},day:[{time:"08:30",vi:"Đọc brief mới, xem lại quy chuẩn nhận diện và tư liệu thương hiệu.",en:"Read the new brief and revisit the brand guidelines and assets."},{time:"10:00",vi:"Phác thảo ba hướng ý tưởng bao bì và chuẩn bị bảng mood.",en:"Sketch three packaging concepts and prepare a mood board."},{time:"13:30",vi:"Dàn trang catalogue, kiểm tra hệ màu, tràn lề, độ phân giải ảnh.",en:"Lay out the catalogue and check colour mode, bleed and image resolution."},{time:"15:30",vi:"Duyệt bản in thử với nhà in, ghi nhận vùng lệch màu cần chỉnh.",en:"Review the proof with the printer and note colour shifts to fix."},{time:"17:00",vi:"Lưu file nguồn, cập nhật thư viện tài sản và hồ sơ giấy phép.",en:"Archive source files and update the asset library and licence records."}],mistakes:{vi:["Gửi file RGB hoặc màu không được quản lý cho nhà in, làm lệch màu thương hiệu.","Phóng to ảnh độ phân giải thấp trong dàn trang mà không kiểm tra độ phân giải hiệu dụng.","Dùng font, ảnh, biểu tượng không có giấy phép thương mại hoặc sao chép ý tưởng logo khác."],en:["Sending RGB or unmanaged colour files to the printer, shifting brand colours.","Scaling up low-resolution images in the layout without checking effective resolution.","Using fonts, photos or icons without a commercial licence, or copying another logo idea."]},career:[{vi:"Thiết kế đồ họa tập sự",en:"Junior graphic designer"},{vi:"Nhà thiết kế đồ họa",en:"Graphic designer"},{vi:"Nhà thiết kế thương hiệu cấp cao",en:"Senior brand designer"},{vi:"Giám đốc nghệ thuật, giám đốc sáng tạo",en:"Art director, creative director"}],glossary:[{term:"CMYK",vi:"Hệ màu trừ dùng bốn mực cyan, magenta, vàng, đen trong in ấn.",en:"The subtractive colour model using cyan, magenta, yellow and black inks in printing."},{term:"Bleed",vi:"Phần hình nền kéo ra ngoài đường xén, thường 3 mm, để không lộ viền trắng khi cắt.",en:"Artwork extended beyond the trim line, usually 3 mm, so no white edge shows after cutting."},{term:"Effective PPI",vi:"Mật độ điểm ảnh thực tế của ảnh sau khi phóng hoặc thu trong dàn trang.",en:"The actual pixel density of an image after it is scaled in the layout."},{term:"Spot colour",vi:"Màu pha sẵn theo bảng màu chuẩn, in bằng mực riêng để giữ màu thương hiệu chính xác.",en:"A premixed colour from a standard guide, printed with its own ink to keep brand colour exact."},{term:"Brand guideline",vi:"Bộ quy chuẩn hướng dẫn sử dụng logo, màu, chữ và hình ảnh của thương hiệu.",en:"The rulebook for using the brand's logo, colours, typography and imagery."}],quiz:[{q:{vi:"Ảnh gốc 300 ppi được đặt ở tỷ lệ 150% trong dàn trang. Độ phân giải hiệu dụng là bao nhiêu?",en:"A 300 ppi image is placed at 150% scale in the layout. What is its effective resolution?"},options:{vi:["450 ppi","300 ppi","150 ppi","200 ppi"],en:["450 ppi","300 ppi","150 ppi","200 ppi"]},answer:3,explain:{vi:"300 / 1.5 = 200 ppi, thấp hơn ngưỡng 300 ppi cho in offset.",en:"300 / 1.5 = 200 ppi, below the 300 ppi offset threshold."}},{q:{vi:"Tràn lề phổ biến cho ấn phẩm in offset là bao nhiêu mỗi cạnh?",en:"What bleed is commonly used per side for offset print?"},options:{vi:["3 mm","0 mm","15 mm","1 mm vào trong"],en:["3 mm","0 mm","15 mm","1 mm inward"]},answer:0,explain:{vi:"Nhà in thường yêu cầu 3 mm tràn lề để bù sai số khi xén giấy.",en:"Printers usually ask for 3 mm bleed to absorb trimming tolerance."}},{q:{vi:"Khách đưa mẫu logo rất giống nhãn hiệu nổi tiếng và yêu cầu làm tương tự. Bạn làm gì?",en:"A client shows a logo very close to a famous trademark and asks for something similar. What do you do?"},options:{vi:["Làm theo vì khách chịu trách nhiệm","Đổi màu một chút là đủ","Giải thích rủi ro nhầm lẫn nhãn hiệu, đề xuất ý tưởng riêng và báo giám đốc sáng tạo","Bỏ dự án mà không giải thích"],en:["Comply because the client is liable","Change the colour slightly","Explain trademark confusion risk, propose an original idea and inform the creative director","Drop the project without explanation"]},answer:2,explain:{vi:"Logo gây nhầm lẫn có thể bị từ chối bảo hộ và bị khởi kiện; cần tư vấn và đề xuất phương án riêng.",en:"A confusing logo can be refused protection and sued; advise the client and offer an original route."}},{q:{vi:"Màu nhận diện cần chính xác tuyệt đối trên bao bì in. Nên dùng gì?",en:"A brand colour must be exact on printed packaging. What should you use?"},options:{vi:["Hệ màu RGB","Màu pha (spot colour)","Ảnh JPEG chất lượng cao","Mã màu web HEX"],en:["RGB colour mode","A spot colour","A high-quality JPEG","A web HEX code"]},answer:1,explain:{vi:"Màu pha in bằng mực riêng nên ổn định hơn pha trộn CMYK, phù hợp màu thương hiệu.",en:"Spot colours use dedicated ink and stay more consistent than CMYK builds, ideal for brand colours."}}],tools_en:["Vector design software","Raster image editing software","Desktop publishing (layout) software","Print file preflight tools","Calibrated monitor and colorimeter","Licensed stock image and font libraries"]}}})})(window.KKR);
